    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    out = [row[:] for row in grid]
    if len(bands) < 2:
        return out

    # Compare repeated vertically aligned bands. The less-filled band receives 1s
    # wherever the corresponding position in the denser band is occupied.
    a, b = bands[0], bands[1]
    count_a = sum(grid[r][c] != bg for r in a for c in range(w))
    count_b = sum(grid[r][c] != bg for r in b for c in range(w))
    if count_a <= count_b:
        target, source = a, b
    else:
        target, source = b, a
    for tr, sr in zip(target, source):
        for c in range(w):
            if grid[tr][c] == bg and grid[sr][c] != bg:
                out[tr][c] = 1
    return out
