{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    active = [r for r,row in enumerate(grid) if any(v != bg for v in row)]
    groups = []
    for r in active:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    out = [row[:] for row in grid]
    # In the last demonstration a single horizontal foreground bar has a short
    # background suffix; the suffix becomes 1, while the full bar remains unchanged.
    if groups:
        for r in active:
            cols = [c for c,v in enumerate(grid[r]) if v != bg]
            if not cols or max(cols) == w-1:
                continue
            lead = 0
            while lead < w and grid[r][lead] != bg:
                lead += 1
            # Choose an incomplete bar row, favoring the longest leading run.
            if lead >= 2:
                for c in range(max(cols)+1, w):
                    out[r][c] = 1
                break
    return out
